const clientEmail = "{{client_email}}";

function getClientEmail(email) {
  const value = (email || "").trim();

  if (!value) {
    return "NOTSET";
  }

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

  if (emailRegex.test(value)) {
    return value;
  }

  return "NOTSET";
}

return getClientEmail(clientEmail);
